package com.shiphappens.logistics.entity;
import jakarta.persistence.*;
@Entity @Table(name="addresses") public class Address { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="address_line1") private String addressLine1; @Column(name="address_line2") private String addressLine2; private String city,state; @Column(name="postal_code") private String postalCode; private String country; public Long getId(){return id;} public String getAddressLine1(){return addressLine1;} public void setAddressLine1(String v){addressLine1=v;} public String getAddressLine2(){return addressLine2;} public void setAddressLine2(String v){addressLine2=v;} public String getCity(){return city;} public void setCity(String v){city=v;} public String getState(){return state;} public void setState(String v){state=v;} public String getPostalCode(){return postalCode;} public void setPostalCode(String v){postalCode=v;} public String getCountry(){return country;} public void setCountry(String v){country=v;} }
